<?php
session_start();
require_once __DIR__ . '/../includes/role_helpers.php';
requireAnyRole(['admin']);
require_once __DIR__ . '/../config/database.php';
$id=(int)($_GET['id']??0);if($id<=0){die('Invalid supplier ID.');}$message='';
$stmt=$conn->prepare("SELECT s.*,u.name,u.username FROM suppliers s LEFT JOIN users u ON u.id=s.user_id WHERE s.id=? LIMIT 1");$stmt->bind_param('i',$id);$stmt->execute();$supplier=$stmt->get_result()->fetch_assoc();$stmt->close();if(!$supplier){die('Supplier profile not found.');}
if($_SERVER['REQUEST_METHOD']==='POST'){
    $supplierName=trim($_POST['supplier_name']??'');$contact=trim($_POST['contact_person']??'');$phone=trim($_POST['phone']??'');$email=trim($_POST['email']??'');$address=trim($_POST['address']??'');
    if($supplierName===''){$message='Supplier name is required.';}elseif($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL)){$message='Enter a valid email.';}else{$stmt=$conn->prepare('UPDATE suppliers SET supplier_name=?,contact_person=?,phone=?,email=?,address=? WHERE id=?');$stmt->bind_param('sssssi',$supplierName,$contact,$phone,$email,$address,$id);$stmt->execute();$stmt->close();header('Location: index.php?updated=1');exit();}
}
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Edit Supplier Profile</title><style>*{box-sizing:border-box;font-family:Arial,sans-serif}.box{width:650px;max-width:90%;margin:50px auto;background:#262740;color:#fff;border:1px solid #3c3e62;border-radius:14px;padding:28px}.group{margin:16px 0}.group label{display:block;font-weight:800;margin-bottom:7px}.group input,.group textarea{width:100%;padding:11px;border-radius:8px;border:1px solid #4a4c71;background:#202036;color:#fff}.group textarea{min-height:100px}.note{color:#b8bdd6}.btn{border:0;padding:11px 17px;border-radius:8px;background:linear-gradient(135deg,#c06ceb,#5df09d);font-weight:900;cursor:pointer}.cancel{display:inline-block;margin-left:6px;padding:11px 17px;background:#202036;color:#fff;text-decoration:none;border-radius:8px}.error{padding:12px;border:1px solid rgba(192,108,235,.4);border-radius:8px}</style><link rel="stylesheet" href="/smart_inventory/assets/admin_shell.css?v=4"><link rel="stylesheet" href="/smart_inventory/assets/dashboard_background.css?v=4"></head><body class="admin-layout"><?php include $_SERVER['DOCUMENT_ROOT'].'/smart_inventory/includes/admin_sidebar.php'; ?><main class="box"><h1>Edit Supplier Profile</h1><p class="note">Linked login: <?php echo htmlspecialchars($supplier['username']??'Legacy / Unlinked'); ?></p><?php if($message): ?><div class="error"><?php echo htmlspecialchars($message); ?></div><?php endif; ?><form method="post"><div class="group"><label>Supplier / Business Name</label><input name="supplier_name" value="<?php echo htmlspecialchars($supplier['supplier_name']); ?>" required></div><div class="group"><label>Contact Person</label><input name="contact_person" value="<?php echo htmlspecialchars($supplier['contact_person']); ?>"></div><div class="group"><label>Phone</label><input name="phone" value="<?php echo htmlspecialchars($supplier['phone']); ?>"></div><div class="group"><label>Email</label><input type="email" name="email" value="<?php echo htmlspecialchars($supplier['email']); ?>"></div><div class="group"><label>Address</label><textarea name="address"><?php echo htmlspecialchars($supplier['address']); ?></textarea></div><button class="btn" type="submit">Save Supplier Profile</button><a class="cancel" href="index.php">Cancel</a></form></main></body></html>
